#include <chrono>

#include <gtest/gtest.h>

#include "bench/supervisor.hpp"

using namespace std::chrono_literals;

TEST(Freshness, FreshUpToMaxAgeAndStaleAfter) {
  bench::Freshness odometry(250ms);
  odometry.on_message({1s});
  EXPECT_TRUE(odometry.fresh({1s + 250ms}));
  EXPECT_FALSE(odometry.fresh({1s + 250ms + 1ns}));
}

#include <array>
#include <chrono>
#include <compare>
#include <format>
#include <iostream>
#include <optional>
#include <string_view>

namespace bench {

// From bench/time.hpp: a reading of a node's clock, in nanoseconds since that clock's zero.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

// Whether a stream of messages is fresh: its last message arrived at most max_age ago. It is
// stale before the first message, and when the clock reads earlier than the last message,
// which happens when a simulation is reset or a replay starts again.
class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds max_age) : max_age_(max_age) {}

  void on_message(Time now) { last_ = now; }

  [[nodiscard]] bool fresh(Time now) const {
    return last_ && *last_ <= now && now.since_epoch - last_->since_epoch <= max_age_;
  }

 private:
  std::chrono::nanoseconds max_age_;
  std::optional<Time> last_;
};

// How long each input may stay silent. Two durations, so the call names them.
struct Timeouts {
  std::chrono::nanoseconds odometry;
  std::chrono::nanoseconds commands;
};

// What the supervisor lets through: commands, or nothing and why.
enum class Gate { open, no_odometry, no_commands };

// What the supervisor's timer does at one tick.
struct Tick {
  Gate gate;     // anything but open: publish a stop now
  bool changed;  // not what it was at the previous tick: log it
};

// The supervisor's rules. A command is forwarded while odometry is fresh, and the timer
// publishes a stop while odometry or the commands are stale.
class Supervisor {
 public:
  explicit Supervisor(Timeouts timeouts) : odometry_(timeouts.odometry), commands_(timeouts.commands) {}

  void on_odometry(Time now) { odometry_.on_message(now); }

  // Records a command's arrival, and returns whether to forward it.
  [[nodiscard]] bool on_command(Time now) {
    commands_.on_message(now);
    return odometry_.fresh(now);
  }

  [[nodiscard]] Gate gate(Time now) const {
    if (!odometry_.fresh(now)) return Gate::no_odometry;
    if (!commands_.fresh(now)) return Gate::no_commands;
    return Gate::open;
  }

  [[nodiscard]] Tick tick(Time now) {
    const Gate current = gate(now);
    const bool changed = current != previous_;
    previous_ = current;
    return {.gate = current, .changed = changed};
  }

 private:
  Freshness odometry_;
  Freshness commands_;
  Gate previous_ = Gate::no_odometry;  // the robot starts held still
};

}  // namespace bench

[[nodiscard]] constexpr std::string_view name(bench::Gate gate) {
  switch (gate) {
    case bench::Gate::open: return "open";
    case bench::Gate::no_odometry: return "no odometry";
    case bench::Gate::no_commands: return "no commands";
  }
  return "?";
}

// One moment of a made-up run: the messages that arrive, then a tick of the timer.
struct Moment {
  std::chrono::milliseconds t;
  bool odometry;
  bool command;
};

int main() {
  using namespace std::chrono_literals;
  const auto at = [](std::chrono::nanoseconds t) { return bench::Time{t}; };

  bench::Freshness odometry(250ms);
  std::cout << std::format("before any message: {}\n", odometry.fresh(at(1s)));
  odometry.on_message(at(1s));
  std::cout << std::format("after 250 ms: {}\n", odometry.fresh(at(1s + 250ms)));
  std::cout << std::format("after 250 ms and 1 ns: {}\n", odometry.fresh(at(1s + 250ms + 1ns)));
  std::cout << std::format("clock went back: {}\n", odometry.fresh(at(900ms)));

  // Odometry pauses from 100 ms to 450 ms; the controller goes quiet after 400 ms.
  constexpr std::array<Moment, 8> run{{{.t = 0ms, .odometry = true, .command = false},
                                       {.t = 50ms, .odometry = true, .command = true},
                                       {.t = 100ms, .odometry = true, .command = true},
                                       {.t = 150ms, .odometry = false, .command = true},
                                       {.t = 400ms, .odometry = false, .command = true},
                                       {.t = 450ms, .odometry = true, .command = false},
                                       {.t = 700ms, .odometry = true, .command = false},
                                       {.t = 950ms, .odometry = true, .command = false}}};
  bench::Supervisor supervisor({.odometry = 250ms, .commands = 500ms});
  for (const Moment& moment : run) {
    if (moment.odometry) supervisor.on_odometry(at(moment.t));
    std::string_view command;
    if (moment.command) command = supervisor.on_command(at(moment.t)) ? "command forwarded, " : "command dropped, ";
    const bench::Tick tick = supervisor.tick(at(moment.t));
    std::cout << std::format("{:3} ms: {}gate {}{}\n", moment.t.count(), command, name(tick.gate),
                             tick.changed ? " (changed)" : "");
  }
}

