namespace bench_nodes {

// The type the bridge in bench_sim takes on /cmd_vel. If yours takes Twist, change it here.
using Command = geometry_msgs::msg::TwistStamped;

// The only publisher on /cmd_vel: forwards /cmd_vel_nav while /odom is fresh, and publishes a
// stop 20 times a second while odometry or the commands are stale.
class Supervisor : public rclcpp::Node {
 public:
  explicit Supervisor(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("supervisor", options), rules_(declare_timeouts()) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    publisher_ = create_publisher<Command>("cmd_vel", qos);
    odometry_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom", qos, [this](const nav_msgs::msg::Odometry&) { rules_.on_odometry(clock_time()); });
    commands_ = create_subscription<Command>("cmd_vel_nav", qos, [this](const Command& command) {
      if (rules_.on_command(clock_time())) publisher_->publish(command);
    });
    timer_ = create_timer(std::chrono::milliseconds(50), [this] { on_tick(); });
  }

 private:
  [[nodiscard]] bench::Timeouts declare_timeouts() {
    return {.odometry = std::chrono::milliseconds(declare_parameter<std::int64_t>("odom_timeout_ms", 250)),
            .commands = std::chrono::milliseconds(declare_parameter<std::int64_t>("cmd_timeout_ms", 500))};
  }

  // The one place that reads the time: the node's clock, handed to the rules.
  [[nodiscard]] bench::Time clock_time() const { return {std::chrono::nanoseconds(now().nanoseconds())}; }

  void on_tick() {
    const bench::Tick tick = rules_.tick(clock_time());
    if (tick.changed) log_gate(tick.gate);
    if (tick.gate != bench::Gate::open) {
      Command stop;
      stop.header.stamp = now();
      stop.header.frame_id = "base_link";
      publisher_->publish(stop);
    }
  }

  void log_gate(bench::Gate gate) const {
    switch (gate) {
      case bench::Gate::open:
        RCLCPP_INFO(get_logger(), "forwarding commands");
        break;
      case bench::Gate::no_odometry:
        RCLCPP_WARN(get_logger(), "odometry is stale: stopping the robot");
        break;
      case bench::Gate::no_commands:
        RCLCPP_INFO(get_logger(), "commands are stale: stopping the robot");
        break;
    }
  }

  bench::Supervisor rules_;
  rclcpp::Publisher<Command>::SharedPtr publisher_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odometry_;
  rclcpp::Subscription<Command>::SharedPtr commands_;
  rclcpp::TimerBase::SharedPtr timer_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::Supervisor>());
  rclcpp::shutdown();
}

