namespace bench_nodes {

// Republishes the bridge's /odom_raw as /odom. The missing-odometry scenario will make it
// stop on cue; for now it forwards every message.
class OdomRelay : public rclcpp::Node {
 public:
  explicit OdomRelay(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("odom_relay", options) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    publisher_ = create_publisher<nav_msgs::msg::Odometry>("odom", qos);
    subscription_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom_raw", qos, [this](const nav_msgs::msg::Odometry& msg) { publisher_->publish(msg); });
  }

 private:
  rclcpp::Publisher<nav_msgs::msg::Odometry>::SharedPtr publisher_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr subscription_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<bench_nodes::OdomRelay>());
  rclcpp::shutdown();
}

#include <chrono>
#include <memory>
#include <vector>

#include <geometry_msgs/msg/twist_stamped.hpp>
#include <nav_msgs/msg/odometry.hpp>
#include <rclcpp/rclcpp.hpp>

namespace bench_nodes {

using Command = geometry_msgs::msg::TwistStamped;  // in the bench: from bench_nodes/supervisor.hpp

enum class Feed { on, off };

// Stands in for the bridge and the controller: while each feed is on, publishes /odom and a
// 0.2 m/s command on /cmd_vel_nav 20 times a second. Keeps the forward speed of every command
// the supervisor sends on /cmd_vel.
class FakeInputs : public rclcpp::Node {
 public:
  explicit FakeInputs(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("fake_inputs", options) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    odometry_ = create_publisher<nav_msgs::msg::Odometry>("odom", qos);
    commands_ = create_publisher<Command>("cmd_vel_nav", qos);
    sent_ = create_subscription<Command>(
        "cmd_vel", qos, [this](const Command& command) { speeds_.push_back(command.twist.linear.x); });
    timer_ = create_timer(std::chrono::milliseconds(50), [this] {
      if (odometry_feed_ == Feed::on) odometry_->publish(nav_msgs::msg::Odometry{});
      if (command_feed_ == Feed::on) {
        Command command;
        command.twist.linear.x = 0.2;
        commands_->publish(command);
      }
    });
  }

  void odometry(Feed feed) { odometry_feed_ = feed; }
  void commands(Feed feed) { command_feed_ = feed; }
  [[nodiscard]] const std::vector<double>& speeds() const { return speeds_; }

 private:
  Feed odometry_feed_ = Feed::off;
  Feed command_feed_ = Feed::off;
  std::vector<double> speeds_;
  rclcpp::Publisher<nav_msgs::msg::Odometry>::SharedPtr odometry_;
  rclcpp::Publisher<Command>::SharedPtr commands_;
  rclcpp::Subscription<Command>::SharedPtr sent_;
  rclcpp::TimerBase::SharedPtr timer_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  auto fake = std::make_shared<bench_nodes::FakeInputs>();
  fake->odometry(bench_nodes::Feed::on);
  fake->commands(bench_nodes::Feed::on);
  rclcpp::spin(fake);
  rclcpp::shutdown();
}

class SupervisorTest : public testing::Test {
 protected:
  static void SetUpTestSuite() { rclcpp::init(0, nullptr); }
  static void TearDownTestSuite() { rclcpp::shutdown(); }

  // Spins both nodes until done() holds or 5 s have passed, and returns done().
  bool spin_until(const std::function<bool()>& done) {
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (!done() && std::chrono::steady_clock::now() < deadline) {
      executor.spin_once(std::chrono::milliseconds(10));
    }
    return done();
  }

  void SetUp() override {
    executor.add_node(supervisor);
    executor.add_node(fake);
  }

  // With 500 ms timeouts, the first stop is due 500 to 550 ms after the last message of either input.
  std::shared_ptr<bench_nodes::Supervisor> supervisor = std::make_shared<bench_nodes::Supervisor>(
      rclcpp::NodeOptions().append_parameter_override("odom_timeout_ms", 500).append_parameter_override(
          "cmd_timeout_ms", 500));
  std::shared_ptr<bench_nodes::FakeInputs> fake = std::make_shared<bench_nodes::FakeInputs>();
  rclcpp::executors::SingleThreadedExecutor executor;
};

TEST_F(SupervisorTest, HoldsTheRobotWithoutOdometry) {
  fake->commands(Feed::on);
  ASSERT_TRUE(spin_until([&] { return std::ranges::count(fake->speeds(), 0.0) >= 5; }));
  EXPECT_EQ(std::ranges::count(fake->speeds(), 0.2), 0);
}

TEST_F(SupervisorTest, ForwardsCommandsWhileOdometryIsFresh) {
  fake->odometry(Feed::on);
  fake->commands(Feed::on);
  EXPECT_TRUE(spin_until([&] { return std::ranges::count(fake->speeds(), 0.2) >= 5; }));
}

TEST_F(SupervisorTest, StopsWhenOdometryStops) {
  fake->odometry(Feed::on);
  fake->commands(Feed::on);
  ASSERT_TRUE(spin_until([&] { return std::ranges::count(fake->speeds(), 0.2) >= 5; }));

  fake->odometry(Feed::off);
  const auto before = std::ssize(fake->speeds());
  const auto since_off = [&] { return fake->speeds() | std::views::drop(before); };
  ASSERT_TRUE(spin_until([&] { return std::ranges::count(since_off(), 0.0) >= 5; }));
  auto after_first_stop = since_off() | std::views::drop_while([](double speed) { return speed != 0.0; });
  EXPECT_EQ(std::ranges::count(after_first_stop, 0.2), 0);
}
